function toast(message){$('claude-toast').textContent=message;$('claude-toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('claude-toast').hidden=true,6500);}
const safe=fn=>async(...args)=>{try{await fn(...args);}catch(e){toast(e.message);}};
async function api(url,{method='GET',body}={}){const response=await fetch(url,{method,credentials:'same-origin',headers:{'Content-Type':'application/json'},signal:AbortSignal.timeout(url.includes('analysis')||url.includes('chat')?180000:90000),...(body===undefined?{}:{body:JSON.stringify(body)})});let data;try{data=await response.json();}catch{throw Error('Servern returnerade inte verifierbara data.');}if(!response.ok||data.ok===false||data.error)throw Error(data.error??`HTTP ${response.status}`);return data;}
function table(headers,rows){return `<div class="ig-table-wrap"><table class="ig-table"><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="ig-muted">Inga verifierade uppgifter.</td></tr>`}</tbody></table></div>`;}
