function showPage(page){S.page=page;document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===`page-${page}`));document.querySelectorAll('aside [data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page));if(page==='strategies')void safe(loadLibrary)();if(page==='chat')void safe(loadResearch)();if(page==='cost')void safe(loadCost)();if(page==='trades')void safe(loadSchedules)();if(page==='trade')setTimeout(()=>chart?.applyOptions({width:$('chart').clientWidth}),20);}
function mergeCatalog(markets){const map=new Map(S.catalog.map(m=>[m.epic,m]));for(const m of markets){const old=map.get(m.epic);map.set(m.epic,{...old,...m,...(old?.quote?.observedAt>(m.quote?.observedAt??0)?{quote:old.quote,bid:old.quote.bid,offer:old.quote.offer,changePercent:old.changePercent}:{}),category:m.category??old?.category});}S.catalog=[...map.values()].filter(m=>['forex','crypto'].includes(m.category));}
function pairRows(){const query=$('ig-pairs-search').value.trim().toLowerCase(),category=$('ig-pairs-category').value,region=$('ig-pairs-region').value;return rankMarkets(S.catalog.filter(m=>(category==='all'||category==='favorites'&&S.favorites.has(m.epic)||m.category===category)&&(region==='all'||instrumentRegions(m).regions.includes(region))&&(!query||`${m.name} ${m.epic}`.toLowerCase().includes(query))),$('ig-rank').value);}
function renderPairs(){$('run-btn').textContent=`▶ Analysera valda (${S.selected.size})`;const rows=pairRows();renderMoney();$('pp-status').textContent=`${S.selected.size} valda · ${rows.length} träffar · analys max10 direkt / session max500${S.analysisReceipt?' · '+S.analysisReceipt:''}`;$('pp-grid').innerHTML=rows.map(m=>`<article class="ig-pair-card"><div style="display:flex;justify-content:space-between"><label><input type="checkbox" data-select="${esc(m.epic)}" ${S.selected.has(m.epic)?'checked':''}> ${esc(m.name)}</label><button data-star="${esc(m.epic)}" aria-label="Favorit ${esc(m.name)}">${S.favorites.has(m.epic)?'★':'☆'}</button></div><small class="ig-muted">${esc(m.epic)} · ${esc(m.marketStatus??m.quote?.marketStatus??'status saknas')}</small><div class="ig-region-tags" title="${esc(instrumentRegions(m).basis)}">${instrumentRegions(m).regions.map(r=>`<span>${esc(r)}</span>`).join('')}</div><small class="ig-muted">${esc(instrumentRegions(m).basis)}</small><div class="ig-quote">${num(m.quote?.bid??m.bid,m.category==='forex'?5:2)}</div><div class="${cls(m.changePercent??m.percentageChange)}">${num(m.changePercent??m.percentageChange)} % IG sessionsförändring</div><div class="ig-muted">Trend ${num(m.trendScore)} · long ${num(m.sentimentLongPercent)} %</div><div class="ig-actions"><button data-chart="${esc(m.epic)}">Diagram</button><button data-pair-analyze="${esc(m.epic)}">Analysera</button><button data-enrich="${esc(m.epic)}">Trend / sentiment</button></div><div>${esc(S.workspace?.analysis?.head?.analyses?.find(a=>a.epic===m.epic)?.reason??'Ingen aktuell agentanalys för paret.')}</div></article>`).join('')||'<p class="ig-muted">Inga hämtade instrument matchar. Hämta IG-katalogen.</p>';}
async function loadCatalog(){const generation=S.generation;$('ig-catalog-status').textContent='Hämtar IG Forex och krypto…';const notes=[];for(const category of ['forex','crypto']){const result=await api(path('directory',{category}));if(generation!==S.generation)return;mergeCatalog((result.markets??[]).map(m=>({...m,category})));notes.push(`${category}: ${S.catalog.filter(m=>m.category===category).length} i sammanfogad lista (${result.markets?.length??0} från senaste katalogsvaret) · ${result.complete?'kategori verifierad':'delvis katalog; fullständighet ej verifierad'}`);renderPairs();}if(generation!==S.generation)return;$('ig-catalog-status').textContent=`${S.catalog.length} instrument visas totalt · `+notes.join(' · ');renderSymbols();if(!S.current){const first=S.catalog.find(m=>m.category===S.category);if(first)await choose(first.epic);}subscribe();}
function renderSymbols(){const select=$('sym-select'),previous=S.current;select.innerHTML='<option value="">Välj verifierat instrument</option>'+S.catalog.filter(m=>m.category===S.category).map(m=>`<option value="${esc(m.epic)}">${esc(m.name)}</option>`).join('');select.value=previous&&[...select.options].some(x=>x.value===previous)?previous:'';$('run-btn').textContent=`▶ Analysera valda (${S.selected.size})`;$('run-btn').title=`IG ${S.mode.toUpperCase()} · ${[...S.selected].map(name).join(' · ')||'Inget valt urval'}`;$('ti-sig').textContent=`${S.catalog.length} hämtade IG-marknader · ${S.selected.size} valda`;$('ig-session-short').textContent=S.workspace?.session?`${S.workspace.session.status} · ${S.workspace.session.epics?.length??0} instrument`:'Ingen agentsession.';}
function initChart(){if(!window.LightweightCharts){$('chart').innerHTML='<p class="ig-note">Diagrammotorn kunde inte laddas.</p>';return;}chart=window.LightweightCharts.createChart($('chart'),{layout:{background:{color:'#050507'},textColor:'#94a3b8'},grid:{vertLines:{color:'#16161c'},horzLines:{color:'#16161c'}},timeScale:{timeVisible:true},rightPriceScale:{borderColor:'#1a1a20'}});candleSeries=chart.addCandlestickSeries({upColor:'#22c55e',downColor:'#ef4444',wickUpColor:'#22c55e',wickDownColor:'#ef4444',borderVisible:false});new ResizeObserver(()=>chart.applyOptions({width:$('chart').clientWidth,height:$('chart').clientHeight})).observe($('chart'));}
function chartData(candles){return candles.filter(c=>[c.openTime,c.open,c.high,c.low,c.close].every(Number.isFinite)).map(c=>({time:Math.floor(c.openTime/1000),open:c.open,high:c.high,low:c.low,close:c.close})).sort((a,b)=>a.time-b.time).filter((c,i,a)=>!i||c.time!==a[i-1].time);}
function instrumentReady(){return !!S.current&&!S.loadingInstrument&&S.market?.epic===S.current;}
function renderChart(fit=false){if(!candleSeries)return;const bars=chartData(instrumentReady()?S.candles:[]);candleSeries.setData(bars);if(fit)chart.timeScale().fitContent();for(const x of indicators)chart.removeSeries(x);indicators=[];for(const button of $('ind-toggles').querySelectorAll('.active')){const type=button.dataset.ind,period=Number(type.replace(/\D/g,'')),ema=type.startsWith('ema');let prev=null;const values=[];for(let i=0;i<bars.length;i++){if(i+1<period)continue;const avg=bars.slice(i-period+1,i+1).reduce((sum,b)=>sum+b.close,0)/period;prev=ema&&prev!==null?bars[i].close*2/(period+1)+prev*(1-2/(period+1)):avg;values.push({time:bars[i].time,value:prev});}const series=chart.addLineSeries({color:type.includes('50')?'#8b5cf6':type.includes('200')?'#fb923c':'#f59e0b',lineWidth:1,lastValueVisible:false,priceLineVisible:false});series.setData(values);indicators.push(series);}}
async function choose(epic,{reset=true}={}){const generation=S.generation,frame=S.timeframe;S.instrumentRevision++;const revision=S.instrumentRevision;S.current=epic;S.market=null;S.candles=[];S.loadingInstrument=revision;reviewCallback=null;$('ig-review').close();$('ot-price').value='';$('ot-est').textContent='Instrumentet laddas · invänta verifierad kvot och granska nytt utkast.';renderSymbols();renderQuote();renderChart();renderStreaming();subscribe();if(reset){$('ot-sl').value='';$('ot-tp').value='';}let market,history;try{[market,history]=await Promise.all([api(path('market',{epic})),api(path('candles',{epic,timeframe:frame,limit:200}))]);if(market?.epic!==epic)throw Error('IG svarade med ett annat instrument än det begärda; underlaget avvisades.');}catch(error){if(generation===S.generation&&revision===S.instrumentRevision){S.current=null;S.market=null;S.candles=[];S.loadingInstrument=null;for(const id of ['ot-price','ot-sl','ot-tp'])$(id).value='';renderSymbols();renderQuote();renderChart();renderStreaming();$('ot-est').textContent='Instrumentdata kunde inte verifieras. Välj instrument igen.';}throw error;}if(generation!==S.generation||revision!==S.instrumentRevision||epic!==S.current||frame!==S.timeframe)return;S.loadingInstrument=null;const liveQuote=S.catalog.find(m=>m.epic===epic)?.quote;S.market=liveQuote&&(liveQuote.observedAt??0)>(market.quote?.observedAt??0)?{...market,quote:liveQuote}:market;S.candles=[...new Map([...(history.candles??[]),...S.candles].map(c=>[c.openTime,c])).values()].sort((a,b)=>a.openTime-b.openTime);S.category=market.category??S.catalog.find(m=>m.epic===epic)?.category??S.category;mergeCatalog([{...market,bid:market.quote?.bid,offer:market.quote?.offer}]);$('cat-select').value=S.category;renderSymbols();renderQuote();renderChart(true);$('sym-select').value=epic;}
function money(value,currency=S.workspace?.connection?.account?.currency){return Number.isFinite(value)&&currency?`${num(value)} ${currency}`:'Saknas · ej verifierat';}
function renderMoney(){renderQueueCapacity();const a=S.workspace?.connection?.account,p=Number($('ig-ticket-margin').value),budget=Number.isFinite(a?.balance)?a.balance*p/100:null;$('ig-money-panel').innerHTML=`<div><small>Kontosaldo · IG ${S.mode.toUpperCase()}</small><b>${money(a?.balance)}</b></div><div><small>Tillgänglig marginal</small><b>${money(a?.available)}</b></div><div><small>Marginalbudget · ${p} %</small><b>${money(budget)}</b></div><p>Kontovaluta ${esc(a?.currency??'saknas')}. ${a?.currency==='SEK'?'Beloppen visas i SEK.':'SEK-omräkning visas inte utan verifierad valutakurs.'} Marginal är säkerhet för CFD-positionen; stopprisk beräknas separat.</p>`;const session=S.workspace?.session;$('ig-session-form').dataset.selectionCount=S.selected.size;const info=$('ig-session-selection');if(info)info.textContent=`${S.selected.size} exakt valda instrument · ${money(Number.isFinite(a?.balance)?a.balance*Number($('ig-session-margin').value)/100:null)} marginaltak per order · max ${$('ig-session-trades').value} nya orderförsök/session`; }
function renderQuote(){renderMoney();const q=instrumentReady()?S.market.quote:null;const value=q?.bid;$('cur-price').textContent=num(value,S.category==='forex'?5:2);$('cur-chg').textContent=num(S.catalog.find(m=>m.epic===S.current)?.changePercent??S.catalog.find(m=>m.epic===S.current)?.percentageChange)+' %';$('d-chg').textContent=$('cur-chg').textContent;$('d-hi').textContent=num(q?.bid,5);$('d-lo').textContent=num(q?.offer,5);$('bk-pair').textContent=name(S.current);$('ig-quote-book').innerHTML=`<div class="ig-grid"><div class="ig-down">Bid / Sälj<br><b class="ig-quote">${num(q?.bid,5)}</b></div><div class="ig-up">Ask / Köp<br><b class="ig-quote">${num(q?.offer,5)}</b></div></div><p class="ig-muted">${esc(q?.marketStatus??'Status saknas')} · ${q?.receivedAt?stamp(q.receivedAt):'Tid saknas'} · ${instrumentReady()&&quoteIsFresh(S.market)?'färsk verifierad kvot':'inaktuell / ej verifierad: senaste IG-tick saknas eller är för gammal; transportanslutning garanterar inte färskt pris'}</p>`;for(const id of ['ot-buy','ot-sell'])$(id).disabled=!instrumentReady()||!quoteIsFresh(S.market);$('ot-price').disabled=S.orderType!=='LIMIT';$('ot-venue').textContent=`IG ${S.mode.toUpperCase()}`;$('ot-avail').textContent=`Tillgängligt: ${num(S.workspace?.connection?.account?.available)} ${S.workspace?.connection?.account?.currency??''}`;}
function signals(){return S.workspace?.analysis?.status==='completed'?S.workspace.analysis.head?.analyses??[]:[];}
function renderAnalysis(){const a=S.workspace?.analysis;$('analysisMeta').textContent=a?`${a.status} · ${stamp(a.completedAt)}`:'Ingen analys har körts.';const rows=signals().map(x=>[esc(name(x.epic)),`<b class="${x.action==='BUY'?'ig-up':x.action==='SELL'?'ig-down':''}">${esc(x.action)}</b>`,esc(x.reason??'Saknas'),num(x.entryLevel,5),num(x.stopLevel,5),num(x.targetLevel,5),`<button class="ig-action" data-copy="${esc(x.epic)}" ${x.action==='HOLD'?'disabled':''}>Till orderutkast</button>`]);$('ig-signals').innerHTML=table(['Instrument','Beslut','Motivering','Entry','SL','TP','Utkast'],rows);$('analysisRows').innerHTML=a?.error?`<p class="ig-status">${esc(a.error)}</p>`:signals().map(x=>`<p><b>${esc(name(x.epic))} · ${esc(x.action)}</b> ${esc(x.reason??'')}</p>`).join('')||'<p class="ig-muted">Inväntar analys. Avvakta är ett giltigt beslut.</p>';const steps=a?.steps??[];const members=[['JEV','Förkontroll',a?.jev?.available===false?'Otillgänglig; se regelunderlag':steps[0]?.status??'Inväntar'],['Teknisk analytiker','Stängda IG-ljus',steps[1]?.status??'Inväntar'],['Hanna / Head Trader','Beslut och kritisk granskning',steps[2]?.status??'Inväntar']];const team=members.map(([label,role,status])=>`<article class="ig-agent"><h4>${label}</h4><p>${esc(status)}</p><small>${role}</small></article>`).join('');$('agent-grid').innerHTML=team;$('agent-grid-page').innerHTML=team;$('team-banner').textContent='JEV förkontroll → två agenter · verkliga händelser, ingen simulerad aktivitet';$('team-banner-page').textContent=$('team-banner').textContent;$('last-turn').textContent=a?.status??'Inväntar';$('timing').textContent=a?.completedAt?`Analys klar ${stamp(a.completedAt)}`:'Ingen verifierad analystid';$('tr-pre').textContent=['CLAUDE TRADING OS / IG',`├─ Miljö: ${S.mode}`,`├─ JEV förkontroll: ${members[0][2]}`,`├─ Teknisk analytiker: ${members[1][2]}`,`└─ Hanna / Head Trader: ${members[2][2]}`,`   ${a?.error??'Alla order granskas manuellt.'}`].join('\n');$('trade-decisions-table').innerHTML=table(['Instrument','Beslut','Motivering'],signals().map(x=>[esc(name(x.epic)),esc(x.action),esc(x.reason)]));}
function positionRows(){return (S.workspace?.positions??[]).map(p=>[esc(p.instrumentName??name(p.epic)),`<b class="${p.direction==='BUY'?'ig-up':'ig-down'}">${esc(p.direction)}</b>`,num(p.size),num(p.level,5),num(p.direction==='BUY'?p.bid:p.offer,5),`<b class="${cls(p.profitLoss)}">${num(p.profitLoss)} ${esc(p.pnlCurrency??p.currency??'')}</b>`,`<button class="ig-action" data-increase="${esc(p.dealId)}">Double up-utkast</button> <button class="ig-action" data-roll="${esc(p.dealId)}">Roll over</button> <button class="ig-action" data-close-position="${esc(p.dealId)}">Stäng</button>`]);}
function renderPositions(){const markup=table(['Instrument','Riktning','Storlek','Entry','Aktuellt','IG P/L','Åtgärder'],positionRows());$('trade-positions-table').innerHTML=markup;$('resOpen').innerHTML=markup;$('positions-list').innerHTML=(S.workspace?.positions??[]).map(p=>`<div class="ig-session-row"><b>${esc(name(p.epic))}</b> ${esc(p.direction)}<p class="${cls(p.profitLoss)}">${num(p.profitLoss)} ${esc(p.pnlCurrency??p.currency??'')}</p><button class="ig-action" data-close-position="${esc(p.dealId)}">Granska stängning</button></div>`).join('')||'<p class="ig-muted">Inga verifierade öppna positioner.</p>';const history=(S.workspace?.history?.transactions??[]).filter(x=>x.cashTransaction===false&&x.type==='DEAL');$('trade-history-table').innerHTML=table(['Datum','Instrument','IG rapporterat resultat'],history.map(x=>[esc(x.date),esc(x.instrumentName),esc(x.profitAndLoss??'Saknas')+' '+esc(x.currency??'')]));$('history').textContent=history.length?`${history.length} hämtade avslut. Full lista under Trades.`:'Inga verifierade avslut.';$('resTrades').innerHTML=$('trade-history-table').innerHTML;const pending=S.workspace?.pendingOrders??[];$('pendingRows').innerHTML=table(['Instrument','Status','Kommentar'],pending.map(x=>[esc(name(x.epic)),esc(x.status),esc(x.error??x.reason??'Avstämning via IG')]));}
function renderSession(){const session=S.workspace?.session;$('session-body').innerHTML=session?`<div class="sess-head"><b>${esc(session.status)}</b> · ${session.epics?.length??0} instrument</div><div class="sess-grid"><div class="sess-cell"><div class="sl">Avslutas Stockholm</div><div>${stamp(session.endsAt)}</div></div><div class="sess-cell"><div class="sl">Nästa analys</div><div>${stamp(session.nextRunAt)}</div></div><div class="sess-cell"><div class="sl">Analyser / cykler</div><div>${num(session.analyses,0)} / ${num(session.cycles,0)}</div></div></div><p class="ig-status">${esc(session.lastError??'Endast analys och manuellt granskade orderförslag.')}</p>`:'<p class="ig-muted">Ingen session. Välj instrument under Alla par.</p>';$('ig-session-stop').disabled=session?.status!=='running';renderSymbols();}
function applySnapshot(w){const previousBinding=S.workspace?.connection?.connectionGeneration,nextBinding=w.connection?.connectionGeneration,bindingChanged=previousBinding!=null&&previousBinding!==nextBinding;if(bindingChanged){S.generation++;S.instrumentRevision++;S.multiRevision++;stopSocket();for(const mini of miniCharts)mini.chart.remove();miniCharts=[];$('mcGrid').innerHTML='';S.current=null;S.market=null;S.candles=[];S.loadingInstrument=null;S.catalog=[];S.research=null;S.analysisReceipt=null;renderResearch();S.strategies=[];S.selected=new Set();S.favorites=new Set();S.schedules=[];S.imported=[];S.streaming=null;S.preferencesRevision=0;selectionDirty=false;reviewCallback=null;$('ig-review').close();renderChart();}S.workspace=w;S.streaming=w.streaming??S.streaming;if(w.preferences){S.favorites=new Set(w.preferences.favorites??[]);S.preferencesRevision=w.preferences.revision??0;}if(!selectionDirty){S.selected=new Set(w.selection?.epics??[]);if(w.selection?.timeframe)$('ig-analysis-frame').value=w.selection.timeframe;}if(w.schedules)S.schedules=w.schedules;if(w.importedSignals)S.imported=w.importedSignals;mergeCatalog((w.markets??[]).filter(m=>m.name).map(m=>({...m,bid:m.quote?.bid,offer:m.quote?.offer})));if(S.current&&!S.loadingInstrument){const market=w.markets?.find(m=>m.epic===S.current);if(market&&(!S.market?.quote?.observedAt||S.market.quote.observedAt<=(market.quote?.observedAt??0)))S.market=market;}render();if(bindingChanged){startSocket();if(w.connection?.status==='connected')Promise.resolve().then(loadCatalog).catch(e=>toast(e.message));}}
function render(){const w=S.workspace,a=w?.connection?.account,currency=a?.currency??'';const connected=w?.connection?.status==='connected';$('port-notice').textContent=`CLAUDE TRADING OS · IG ${S.mode.toUpperCase()} · ${connected?'kontot anslutet':'ej anslutet'} · samma IG-motor som nya systemet · endast verifierad data`;$('conn-dot').className=`dot ${connected?'live':''}`;$('pnl').textContent=`${num(a?.profitLoss)} ${currency}`;$('pnl').className=`pnl ${cls(a?.profitLoss)}`;for(const [mode,id] of [['demo','pb-equity'],['live','lb-equity']]){const connection=mode===S.mode?(w?.connection??S.accounts[mode]):S.accounts[mode],account=connection?.account;$(id).textContent=connection?.status==='connected'&&Number.isFinite(account?.balance)?`${num(account.balance)} ${account.currency??''}`:'Ej anslutet';}$('ig-account-summary').innerHTML=table(['Miljö','Kontovärde','Tillgängligt','IG P/L'],[[`IG ${S.mode.toUpperCase()}`,num(a?.balance)+' '+esc(currency),num(a?.available)+' '+esc(currency),num(a?.profitLoss)+' '+esc(currency)]]);$('sl-balance').innerHTML=$('ig-account-summary').innerHTML;$('resTotals').innerHTML=$('ig-account-summary').innerHTML;$('ti-mode').textContent=`IG ${S.mode.toUpperCase()} · ${w?.execution?.reason??'Ordergrind inväntas'}`;$('ig-settings-status').textContent=w?.connection?.error??`IG ${S.mode.toUpperCase()} · ${w?.connection?.status??'saknas'}`;renderQuote();renderAnalysis();renderPositions();renderSession();renderPairs();renderSchedules();renderStreaming();renderStrategies();renderMemory();renderSymbols();$('mvRows').innerHTML=table(['Instrument','IG sessionsförändring'],rankMarkets(S.catalog,'movement').slice(0,8).map(m=>[esc(m.name),`<b class="${cls(m.changePercent??m.percentageChange)}">${num(m.changePercent??m.percentageChange)} %</b>`]));}
async function loadAccounts(){const result=await api('/api/ig/status');S.accounts=Object.fromEntries(['demo','live'].map(mode=>{const c=result.environments?.[mode];return [mode,{status:c?.status,account:c?.account?{balance:c.account.balance,currency:c.account.currency}:null}];}));render();}
async function refresh(){const generation=S.generation,w=await api(path('workspace'));if(generation===S.generation)applySnapshot(w);}
async function connect(){const generation=S.generation,result=await api('/api/ig/connect',{method:'POST',body:{environment:S.mode}});if(generation!==S.generation)return;const connection=result.environments?.[S.mode];if(connection?.status!=='connected')throw Error(connection?.error??'IG kunde inte verifieras');await refresh();await loadCatalog();}
async function setMode(mode){if(mode===S.mode)return;S.mode=mode;S.generation++;S.instrumentRevision++;S.multiRevision++;for(const mini of miniCharts)mini.chart.remove();miniCharts=[];$('mcGrid').innerHTML='';stopSocket();S.current=null;S.market=null;S.candles=[];S.loadingInstrument=null;S.catalog=[];S.workspace=null;S.research=null;S.analysisReceipt=null;renderResearch();S.selected=new Set();S.favorites=new Set();S.schedules=[];S.strategies=[];S.preferencesRevision=0;selectionDirty=false;reviewCallback=null;$('ig-review').close();$('broker-select').value=mode;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));render();renderChart();startSocket();await refresh();if(S.workspace?.connection?.status==='connected')await loadCatalog();}
async function saveSelection(payload=selected()){const generation=S.generation;selectionDirty=true;if(payload.epics.length>500)throw Error('Högst 500 instrument per agentsession.');if(payload.epics.length>10){toast(`${payload.epics.length} instrument hålls som exakt lokalt sessionsurval; direktanalys stöder högst 10.`);return;}try{await api('/api/ig/selection',{method:'POST',body:{environment:payload.environment,epics:payload.epics,timeframe:payload.timeframe,percent:payload.percent,horizonMinutes:payload.horizonMinutes}});if(generation===S.generation)toast(`${S.selected.size} instrument sparade på IG-servern`);}finally{if(generation===S.generation&&S.selected.size<=10)selectionDirty=false;}}
async function analyze(){if(busy)throw Error('En analys pågår redan i denna klient.');if(!S.selected.size||S.selected.size>10)throw Error('Välj1–10 instrument för direktanalys. Större urval körs i en agentsession.');const generation=S.generation,mode=S.mode,binding=S.workspace?.connection?.connectionGeneration,payload=selected();busy=true;$('run-btn').disabled=true;$('analysisRows').textContent=`IG ${mode.toUpperCase()} · begärt exakt urval: ${payload.epics.map(name).join(' · ')}. JEV → Teknisk analytiker → Hanna arbetar…`;S.analysisReceipt=$('analysisRows').textContent;$('pp-status').textContent=S.analysisReceipt;try{await saveSelection(payload);if(generation!==S.generation||mode!==S.mode||binding!==S.workspace?.connection?.connectionGeneration)throw Error('Kontot ändrades; analysen avbröts.');const result=await api('/api/ig/analysis',{method:'POST',body:payload});if(generation===S.generation){await refresh();if(generation!==S.generation||mode!==S.mode||binding!==S.workspace?.connection?.connectionGeneration)return;const receipt=`IG ${mode.toUpperCase()} · begärt: ${payload.epics.map(name).join(' · ')} · serversvar: ${(result.selection?.epics??[]).map(name).join(' · ')||'urval saknas i svaret'}`;$('analysisRows').insertAdjacentHTML('afterbegin',`<p>${esc(receipt)}</p>`);S.analysisReceipt=receipt;$('pp-status').textContent=receipt;}}finally{busy=false;$('run-btn').disabled=false;}}
function review(title,markup,callback){reviewCallback={generation:S.generation,binding:S.workspace?.connection?.connectionGeneration,callback};$('ig-review-title').textContent=title;$('ig-review-body').innerHTML=markup;$('ig-review-confirm').disabled=false;$('ig-review').showModal();}
async function preview(direction){if(![1,2,3].includes(Number($('ig-ticket-margin').value)))throw Error('Marginalbudget måste vara 1–3 %.');if(!instrumentReady()||!quoteIsFresh(S.market))throw Error('Verifierat instrument och färsk IG-kvot krävs.');const generation=S.generation,epic=S.current,revision=S.instrumentRevision,binding=S.workspace?.connection?.connectionGeneration;const draft=await api('/api/ig/order-preview',{method:'POST',body:{environment:S.mode,epic:S.current,direction,size:Number($('ot-amt').value),entry:S.orderType==='LIMIT'?Number($('ot-price').value):direction==='BUY'?S.market.quote.offer:S.market.quote.bid,stopLevel:Number($('ot-sl').value),targetLevel:Number($('ot-tp').value),orderType:S.orderType,holdingMinutes:S.holding,autoClose:$('ig-auto-close').checked}});if(generation!==S.generation||epic!==S.current||revision!==S.instrumentRevision||binding!==S.workspace?.connection?.connectionGeneration)throw Error('Instrumentet eller kontot ändrades; granska igen.');const account=S.workspace?.connection?.account,budget=account?.balance*Number($('ig-ticket-margin').value)/100;if(draft.currency!==account?.currency||!Number.isFinite(budget)||!Number.isFinite(draft.margin)||draft.margin>budget)throw Error('Serverns marginalkrav överstiger vald marginalbudget eller saknar verifierad kontovaluta. Minska kontraktsstorleken.');$('ot-est').innerHTML=`<b>Serververifierad förhandsgranskning</b><br>Marginal ${money(draft.margin,draft.currency)} · stopprisk ${money(draft.risk,draft.currency)} · exponering ${money(draft.exposure,draft.currency)}`;review(`Granska ${direction==='BUY'?'Köp / Long':'Sälj / Short'} · IG ${S.mode.toUpperCase()}`,table(['Fält','Serverberäknat'],[['Instrument',esc(name(draft.epic??epic))],['Entry',num(draft.entry,5)],['Storlek',num(draft.size??Number($('ot-amt').value))],['Stopprisk',money(draft.risk,draft.currency)],['Marginalkrav',money(draft.margin,draft.currency)],['Exponering',money(draft.exposure,draft.currency)],['Kontovaluta',esc(draft.currency??'saknas')],['Exekveringsvaluta',esc(draft.executionCurrency??'saknas')],['Giltig till',stamp(draft.expiresAt)]])+`<p class="ig-note">${esc(draft.blocker??draft.reason??'Bekräftelsen skickar en order till vald IG-miljö. Stopprisk kan påverkas av gap och slippage.')}</p>`,async()=>{const result=await api('/api/ig/order-confirm',{method:'POST',body:{environment:S.mode,draftId:draft.id}});toast(result.error??`IG-orderstatus: ${result.status}`);await refresh();});if(S.workspace?.execution?.enabled!==true)$('ig-review-confirm').disabled=true;}
async function copySignal(epic){const a=S.workspace?.analysis,row=signals().find(x=>x.epic===epic),validUntil=(a?.completedAt??0)+Math.min(900000,(frames[a?.selection?.timeframe]??300)*1000);if(!row||row.action==='HOLD'||Date.now()>=validUntil||![row.stopLevel,row.targetLevel].every(Number.isFinite))throw Error('Analysen är utgången eller saknar verifierade nivåer.');const generation=S.generation;await choose(epic);if(generation!==S.generation||!quoteIsFresh(S.market)||Date.now()>=validUntil)throw Error('Färsk IG-kvot eller giltig signal saknas.');$('ot-sl').value=row.stopLevel;$('ot-tp').value=row.targetLevel;S.orderType='MARKET';renderQuote();showPage('trade');toast(`${row.action} kopierad till utkast. Granska motsvarande Köp/Sälj separat.`);}
function renderStrategies(){$('sl-list').innerHTML=S.strategies.length?[...S.strategies.filter(s=>s.kind!=='research_candidate'),...S.strategies.filter(s=>s.kind==='research_candidate')].map((s,i,all)=>`${s.kind==='research_candidate'&&all[i-1]?.kind!=='research_candidate'?'<h3>Researchkandidater · ej körbara</h3>':''}<article class="sl-strat"><div class="sl-strat-h"><b>${esc(s.name)}</b><span class="sl-badge test">${esc(s.status??'Ej validerad')}</span><span>${esc(s.instrument??s.side??'Se regler')} · ${esc(s.timeframe??'')}</span></div>${s.kind==='research_candidate'?`<p class="ig-note">Ej körbar · ${esc(s.availability??'källa saknas')} · warmup ${s.warmupBars??'ej verifierad'} · ingen aktivering eller regeltest.</p>`:''}<p class="sl-rules">${esc((s.notes??[]).join(' ')||s.description||'Ingen verifierad lönsamhetsuppgift.')}</p><details><summary>Källa och exakta regler</summary><pre class="ig-pre">${esc(JSON.stringify({source:s.source,entry:s.entry,exit:s.exit,stop:s.stop},null,2))}</pre></details></article>`).join(''):'<p class="ig-muted">Strategiregistret är inte hämtat.</p>';const observations=S.workspace?.analysis?.technical?.observations??[];$('sl-signals').innerHTML=observations.map(o=>`<h4>${esc(name(o.epic))}</h4>${table(['Strategi','Status','Entry','Exit','Motivering'],(o.strategyComparisons??[]).map(x=>[esc(x.name??x.id??x.strategyId),esc(x.status),x.entrySignal===true?'Uppfylld':x.entrySignal===false?'Ej uppfylld':'Saknas',x.exitCondition===true?'Uppfylld':x.exitCondition===false?'Ej uppfylld':'Saknas',esc(x.reason)]))}`).join('')||'<p class="ig-muted">Ingen jämförelse har returnerats av IG-analysen.</p>';}
function renderMemory(){const memory=S.workspace?.analysisMemory;$('ig-memory').innerHTML=memory?`<p>${esc(memory.status)} · ${num(memory.recordCount,0)} poster</p><p class="ig-note">Ingen verifierad P/L eller automatisk självträning.</p>${(memory.recentDecisions??[]).map(x=>`<div class="ig-session-row"><b>${stamp(x.at)} · ${esc(x.timeframe)}</b>${(x.decisions??[]).map(d=>`<p>${esc(name(d.epic))} · ${esc(d.action)} · ${esc(d.reason)}</p>`).join('')}</div>`).join('')}`:'<p class="ig-muted">Analysminne saknas i serverns snapshot.</p>';}
async function loadResearch(){const generation=S.generation,result=await api(path('research'));if(generation!==S.generation)return;S.research=result;renderResearch();}
function renderResearch(){const r=S.research;$('team-chat-log').innerHTML=(r?.messages??[]).map(m=>`<article class="ig-chat-message"><b>${esc(({user:'Du',technical:'Teknisk analytiker',head:'Hanna / Head Trader'})[m.role]??m.role)}</b><p>${esc(m.text)}</p><small class="ig-muted">${stamp(m.at)}</small></article>`).join('')||'<p class="ig-muted">Inga sparade meddelanden. Chatten diskuterar strategier och kan inte skicka order.</p>';$('ig-sources').innerHTML=(r?.sources??[]).map(x=>`<div class="ig-session-row"><b>${esc(x.name)}</b> · ${esc(x.kind==='link'?'Länkreferens, ej inläst':'Textfil, opålitligt användarunderlag')}</div>`).join('')||'<p class="ig-muted">Inga sparade källor.</p>';$('ig-baseline').innerHTML=(r?.baselines??[]).map(b=>`<option value="${esc(b.id)}">${esc(b.name)} · ${esc(b.timeframe)}</option>`).join('');$('ig-library-drafts').innerHTML=(r?.strategies??[]).map(x=>`<article class="sl-strat"><b>${esc(x.name)}</b> · UTKAST<p class="sl-rules">${esc(x.specification)}</p>${r.baselines?.find(b=>b.id===x.baselineId)?.kind==='research_candidate'?'<p class="ig-note">Researchkandidat · ej körbar, källunderlag saknas. Regeltest är inte tillgängligt.</p>':`<button class="ig-action" data-rule-test="${esc(x.id)}">Kontrollera basregler på valt IG-instrument</button>`}${(x.tests??[]).map(t=>`<details><summary>${stamp(t.at)} · ${esc(t.note)}</summary><pre class="ig-pre">${esc(JSON.stringify(t.result,null,2))}</pre></details>`).join('')}</article>`).join('');$('ig-research-status').textContent=r?`Kontoavgränsat bibliotek · revision ${r.revision} · JEV→Teknisk analytiker→Hanna`:'Biblioteket är ej hämtat.';}
async function researchMutation(body,route='research'){const generation=S.generation,mode=S.mode,binding=S.workspace?.connection?.connectionGeneration;if(!S.research)await loadResearch();if(generation!==S.generation||mode!==S.mode)throw Error('Kontot ändrades; forskningsåtgärden avbröts.');if(!S.research||S.research.connectionGeneration!==binding)throw Error('Bibliotekets kontosession är inaktuell. Hämta om.');const result=await api('/api/ig/'+route,{method:'POST',body:{environment:S.mode,connectionGeneration:binding,revision:S.research.revision,...body}});if(generation!==S.generation||S.workspace?.connection?.connectionGeneration!==binding)return;S.research=result;renderResearch();}
async function loadLibrary(){const generation=S.generation,result=await api(path('strategies'));if(generation!==S.generation)return;S.strategies=result.strategies??[];renderStrategies();await Promise.allSettled([loadResearch(),loadCourse()]).then(results=>results.forEach(r=>{if(r.status==='rejected')toast(r.reason.message);}));}
async function loadCourse(){const generation=S.generation,result=await api('/api/course');if(generation!==S.generation)return;$('ig-course').innerHTML=`<h4>${esc(result.name??'Kursstrategi')}</h4><p>${esc(result.symbol??'')} · ${esc(result.interval??'')} · ${esc(result.status)}</p><p class="ig-status">${esc(result.note??'Underlag saknas')}</p>${result.metrics?`<pre class="ig-pre">${esc(JSON.stringify({metrics:result.metrics,inputIdentity:result.inputIdentity},null,2))}</pre>`:''}`;$('ig-course-run').disabled=result.canRun!==true;}
async function loadCost(){const generation=S.generation,cost=await api('/api/cost');if(generation!==S.generation)return;const total=cost.today?.totalUsd??cost.dailyUsd??cost.todayUsd;$('cost-today').textContent=Number.isFinite(total)?`$${num(total)}`:'Saknas';$('ig-cost').innerHTML=`<div class="ig-cost-number">${Number.isFinite(total)?'$'+num(total):'Kostnad saknas'}</div><p class="ig-muted">Befintlig backend redovisar faktiskt registrerade AI-anrop och budgetstatus.</p><pre class="ig-pre">${esc(JSON.stringify(cost,null,2))}</pre>`;}
function renderQueueCapacity(){const result=sessionCapacity(S.selected.size,Number($('ig-session-duration').value),Number($('ig-session-interval').value));$('ig-session-capacity').textContent=result.note;$('ig-schedule-capacity').textContent='Schema använder samma sessionsinställningar: '+result.note;return result;}
